import React, { useEffect, useState } from 'react';
import axios from 'axios';
import './posts.css';

const Posts = ({ setMessage }) => {
  const [posts, setPosts] = useState([]);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const [commentInputs, setCommentInputs] = useState({});

  const currentUser = JSON.parse(localStorage.getItem('user'));
  const accessToken = localStorage.getItem('accessToken');

  useEffect(() => {
    const fetchPosts = async () => {
      setLoading(true);
      try {
        if (!accessToken) {
          throw new Error('No authentication token found.');
        }
        console.log('Posts: Fetching posts...');
        const res = await axios.get('http://localhost:5000/api/posts', {
          headers: { Authorization: `Bearer ${accessToken}` },
        });
        console.log('Posts: Fetched posts=', res.data);
        setPosts(res.data);
        setError(null);
      } catch (err) {
        console.error('Posts: Error fetching posts:', err.message);
        setError(err.response?.data?.message || 'Failed to fetch posts');
        setMessage(err.response?.data?.message || 'Failed to fetch posts');
      } finally {
        setLoading(false);
      }
    };

    fetchPosts();

    const handleNewPost = () => {
      fetchPosts();
    };

    window.addEventListener('newPost', handleNewPost);

    return () => {
      window.removeEventListener('newPost', handleNewPost);
    };
  }, [accessToken, setMessage]);

  const handleLike = async (postId) => {
    try {
      if (!accessToken) {
        throw new Error('No authentication token found.');
      }
      console.log(`Posts: Toggling like for post ${postId}`);
      const res = await axios.post(
        `http://localhost:5000/api/posts/${postId}/like`,
        { userId: currentUser._id },
        { headers: { Authorization: `Bearer ${accessToken}` } }
      );
      console.log(`Posts: Like response:`, res.data);
      setPosts((prev) =>
        prev.map((post) =>
          post._id === postId
            ? {
                ...post,
                likesCount: res.data.likesCount,
                likedBy: res.data.likedBy,
              }
            : post
        )
      );
    } catch (err) {
      console.error('Posts: Error toggling like:', err.message);
      setError(err.response?.data?.message || 'Failed to like post');
    }
  };

  const handleCommentSubmit = async (postId, e) => {
    e.preventDefault();
    const content = commentInputs[postId]?.trim();
    if (!content) return;

    try {
      if (!accessToken) {
        throw new Error('No authentication token found.');
      }
      console.log(`Posts: Submitting comment for post ${postId}: ${content}`);
      const res = await axios.post(
        `http://localhost:5000/api/posts/${postId}/comment`,
        { userId: currentUser._id, content },
        { headers: { Authorization: `Bearer ${accessToken}` } }
      );
      console.log(`Posts: Comment response:`, res.data);
      setPosts((prev) =>
        prev.map((post) =>
          post._id === postId
            ? {
                ...post,
                commentsCount: res.data.commentsCount,
                comments: [
                  ...(post.comments || []),
                  res.data.newComment,
                ],
              }
            : post
        )
      );
      setCommentInputs((prev) => ({ ...prev, [postId]: '' }));
    } catch (err) {
      console.error('Posts: Error submitting comment:', err.message);
      setError(err.response?.data?.message || 'Failed to add comment');
    }
  };

  if (loading) {
    return <div>Loading posts...</div>;
  }

  if (error) {
    return <div className="error">{error}</div>;
  }

  return (
    <div className="posts-container">
      {posts.length === 0 ? (
        <p>No posts available.</p>
      ) : (
        posts.map((post) => (
          <div key={post._id} className="post">
            <div className="post-header">
              <img
                src={post.userId?.profilePicture || '/default-profile.png'}
                alt="Profile"
                className="profile-pic"
              />
              <div>
                <h3>{post.userId?.name || 'Unknown User'}</h3>
                <p>{post.location || 'No location'}</p>
              </div>
            </div>
            <p className="post-desc">{post.desc || ''}</p>
            {post.media && (
              <div className="post-media">
                {post.media.endsWith('.mp4') || post.media.endsWith('.mov') ? (
                  <video controls>
                    <source src={`http://localhost:5000${post.media}`} type="video/mp4" />
                    Your browser does not support the video tag.
                  </video>
                ) : (
                  <img
                    src={`http://localhost:5000${post.media}`}
                    alt="Post content"
                    className="post-img"
                  />
                )}
              </div>
            )}
            <div className="post-actions">
              <button
                className={`like-btn ${post.likedBy?.includes(currentUser._id) ? 'liked' : ''}`}
                onClick={() => handleLike(post._id)}
                disabled={loading}
              >
                {post.likedBy?.includes(currentUser._id) ? 'Unlike' : 'Like'}
              </button>
              <span>{post.likesCount} Likes</span>
              <span>{post.commentsCount} Comments</span>
            </div>
            <div className="comments-section">
              <form onSubmit={(e) => handleCommentSubmit(post._id, e)}>
                <input
                  type="text"
                  placeholder="Add a comment..."
                  value={commentInputs[post._id] || ''}
                  onChange={(e) =>
                    setCommentInputs((prev) => ({
                      ...prev,
                      [post._id]: e.target.value,
                    }))
                  }
                  disabled={loading}
                />
                <button type="submit" disabled={loading || !commentInputs[post._id]?.trim()}>
                  Post
                </button>
              </form>
              {post.comments && post.comments.length > 0 && (
                <div className="comments-list">
                  {post.comments.map((comment) => (
                    <div key={comment._id} className="comment">
                      <strong>{comment.userId?.name || 'Unknown'}</strong>: {comment.content}
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        ))
      )}
    </div>
  );
};

export default Posts;
